  "publishes (works only while connected)": "ينشر (يعمل فقط أثناء الاتصال)",
  "retained option, 1 = ON, 0 = OFF; call it before mqtt_publish": "خيار retained، 1 = تشغيل، 0 = إيقاف؛ استدعِه قبل mqtt_publish",
  "the answer arrives in html_mqtt_status": "تصل الإجابة في html_mqtt_status",
  "disconnects (note the capital D)": "يقطع الاتصال (لاحظ حرف D الكبير)",
  "HTTP POST of {\"key\":\"value\"}": "HTTP POST بقيمة {\"key\":\"value\"}",
